using Dominio.Entidades; using Infraestructura.Data; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using System.Security.Claims;
namespace PuntoHalcon.Controllers;
[Authorize] public class EvidenciasController:Controller
{
 private readonly PuntoHalconDbContext _db; public EvidenciasController(PuntoHalconDbContext db){_db=db;} private int UsuarioId=>int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Crear(string categoria,string nombre,string descripcion,string institucion,string tipo,DateTime? fecha,IFormFile? archivo){if(string.IsNullOrWhiteSpace(nombre)){TempData["Error"]="Escribe un nombre para el registro.";return Volver(categoria);}var e=new Evidencia{UsuarioId=UsuarioId,Categoria=categoria,Nombre=nombre.Trim(),Descripcion=(descripcion??"").Trim(),Institucion=(institucion??"").Trim(),Tipo=(tipo??"").Trim(),Fecha=fecha};if(archivo!=null&&archivo.Length>0){var ext=Path.GetExtension(archivo.FileName).ToLower();var permitidas=new[]{".pdf",".png",".jpg",".jpeg",".webp"};if(!permitidas.Contains(ext)){TempData["Error"]="Solo se permiten archivos PDF o imágenes.";return Volver(categoria);}var dir=Path.Combine(Directory.GetCurrentDirectory(),"wwwroot","uploads");Directory.CreateDirectory(dir);var file=Guid.NewGuid()+ext;using var fs=System.IO.File.Create(Path.Combine(dir,file));await archivo.CopyToAsync(fs);e.ArchivoRuta="/uploads/"+file;} _db.Evidencias.Add(e);await _db.SaveChangesAsync();TempData["Ok"]="El registro se guardó correctamente.";return Volver(categoria);}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Eliminar(int id){var e=await _db.Evidencias.FirstOrDefaultAsync(x=>x.EvidenciaId==id&&x.UsuarioId==UsuarioId);if(e==null)return NotFound();if(!string.IsNullOrEmpty(e.ArchivoRuta)){var p=Path.Combine(Directory.GetCurrentDirectory(),"wwwroot",e.ArchivoRuta.TrimStart('/').Replace('/',Path.DirectorySeparatorChar));if(System.IO.File.Exists(p))System.IO.File.Delete(p);}var c=e.Categoria;_db.Evidencias.Remove(e);await _db.SaveChangesAsync();TempData["Ok"]="Registro eliminado.";return Volver(c);}
 private IActionResult Volver(string c)=>RedirectToAction(c=="Academica"?"FormacionAcademica":c=="Extracurricular"?"FormacionExtra":c=="Proyecto"?"Proyectos":"Evidencias","Home");
}
